<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acceso estudiantes</title><style>*{box-sizing:border-box}body{font-family:Arial;background:#eef2ff;color:#172554;padding:24px}.card{max-width:700px;margin:4vh auto;background:#fff;border-radius:20px;padding:28px}label{display:block;font-weight:bold;margin:15px 0 5px}input,select,button{width:100%;padding:13px;border:1px solid #94a3b8;border-radius:9px;font-size:16px}button{margin-top:15px;background:#1d4ed8;color:#fff;border:0;font-weight:bold}.hidden{display:none}.error{color:#b91c1c;margin-top:10px}.test{display:block;padding:14px;margin:10px 0;background:#eff6ff;border-radius:10px}.version{position:fixed;right:12px;bottom:8px;color:#64748b}</style></head><body><main class="card"><h1>Pruebas de estudiantes</h1><section id="login"><label for="school">Colegio</label><select id="school" disabled><option value="">Cargando colegios…</option></select><p id="schoolName"></p><label for="course">Curso</label><select id="course" disabled><option value="">Selecciona el curso</option></select><label for="student">Estudiante</label><select id="student" disabled><option value="">Selecciona tu nombre</option></select><label for="pin">PIN del curso</label><input id="pin" type="password"><button id="enter">Ingresar</button><p id="error" class="error"></p></section><section id="panel" class="hidden"><h2 id="welcome"></h2><div id="tests"></div><button id="logout">Salir</button></section></main><div class="version">v2.1.0</div><script>
const api='portal_estudiante_api.php',school=document.querySelector('#school'),course=document.querySelector('#course'),student=document.querySelector('#student'),error=document.querySelector('#error'),schoolName=document.querySelector('#schoolName'),login=document.querySelector('#login'),panel=document.querySelector('#panel'),welcome=document.querySelector('#welcome'),tests=document.querySelector('#tests'),pin=document.querySelector('#pin');const requestedSchool=new URLSearchParams(location.search).get('colegio')||'';async function req(url,opt){const r=await fetch(url,opt),x=await r.json();if(!r.ok&&!x.error)x.error='No se pudo completar la solicitud.';return x}function options(rows,valueKey,labelKey,prompt){return[{value:'',label:prompt},...rows.map(r=>({value:String(r[valueKey]),label:String(r[labelKey])}))]}function setOptions(select,rows){select.replaceChildren(...rows.map(row=>{const option=document.createElement('option');option.value=row.value;option.textContent=row.label;return option}))}async function loadCourses(){course.disabled=true;student.disabled=true;setOptions(course,options([], 'id','nombre','Cargando cursos…'));setOptions(student,options([], 'public_id','nombre','Selecciona tu nombre'));error.textContent='';if(!school.value){schoolName.textContent='';setOptions(course,options([], 'id','nombre','Selecciona el curso'));return}const x=await req(api+'?action=courses&colegio='+encodeURIComponent(school.value));if(!x.ok){error.textContent=x.error;setOptions(course,options([], 'id','nombre','Selecciona el curso'));return}schoolName.textContent=x.colegio;setOptions(course,options(x.cursos,'id','nombre','Selecciona el curso'));course.disabled=x.cursos.length===0;if(x.cursos.length===0)error.textContent='Este colegio todavía no tiene cursos con estudiantes.'}async function loadSchools(){try{const x=await req(api+'?action=schools');if(!x.ok)throw new Error(x.error);setOptions(school,options(x.colegios,'codigo','nombre','Selecciona tu colegio'));school.disabled=false;if(requestedSchool&&x.colegios.some(c=>c.codigo===requestedSchool.toLowerCase()))school.value=requestedSchool.toLowerCase();else if(x.colegios.length===1)school.value=x.colegios[0].codigo;if(school.value)await loadCourses();if(x.colegios.length===0)error.textContent='No hay colegios habilitados.'}catch(e){setOptions(school,options([], 'codigo','nombre','No se pudieron cargar los colegios'));error.textContent=e.message||'No se pudieron cargar los colegios.'}}school.onchange=loadCourses;course.onchange=async()=>{student.disabled=true;setOptions(student,options([], 'public_id','nombre','Cargando estudiantes…'));error.textContent='';if(!course.value){setOptions(student,options([], 'public_id','nombre','Selecciona tu nombre'));return}const x=await req(api+'?action=students&colegio='+encodeURIComponent(school.value)+'&curso='+encodeURIComponent(course.value));if(!x.ok){error.textContent=x.error;setOptions(student,options([], 'public_id','nombre','Selecciona tu nombre'));return}setOptions(student,options(x.estudiantes,'public_id','nombre','Selecciona tu nombre'));student.disabled=x.estudiantes.length===0;if(x.estudiantes.length===0)error.textContent='No hay estudiantes activos en este curso.'};enter.onclick=async()=>{const x=await req(api,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'login',colegio:school.value,curso:course.value,estudiante:student.value,pin:pin.value})});if(!x.ok){error.textContent=x.error;return}session()};async function session(){const x=await req(api+'?action=session');if(!x.authenticated)return;login.classList.add('hidden');panel.classList.remove('hidden');welcome.textContent=x.estudiante.nombre+' — '+x.estudiante.curso;tests.replaceChildren();if(!x.pruebas.length){tests.textContent='No hay pruebas asignadas.';return}x.pruebas.forEach(p=>{const a=document.createElement('a');a.className='test';a.href='rendir_prueba.php?id='+encodeURIComponent(p.id);a.textContent=p.asignatura+': '+p.titulo;tests.appendChild(a)})}logout.onclick=async()=>{await req(api,{method:'POST',headers:{'Content-Type':'application/json'},body:'{"action":"logout"}'});location.reload()};loadSchools();session();
</script><script src="marca.js"></script></body></html>
